-- ===========================================================================================
-- Part 2: database-enforced invariants (defence in depth behind src/iam)
-- ===========================================================================================

-- Identity: one normalised e-mail per user; only Argon2id hashes; counters never negative.
ALTER TABLE "User"
  ADD CONSTRAINT "User_emailNormalized_check"
    CHECK ("emailNormalized" = lower(btrim("email")) AND "emailNormalized" <> ''),
  ADD CONSTRAINT "User_passwordHash_argon2id_check"
    CHECK ("passwordHash" IS NULL OR "passwordHash" LIKE '$argon2id$%'),
  ADD CONSTRAINT "User_counters_check"
    CHECK ("failedLoginCount" >= 0 AND "securityVersion" >= 0);

ALTER TABLE "Site"
  ADD CONSTRAINT "Site_primaryDomain_check" CHECK ("primaryDomain" = lower("primaryDomain")),
  ADD CONSTRAINT "Site_defaultLocale_check"
    CHECK ("defaultLocale" ~ '^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$');

ALTER TABLE "FeatureModule"
  ADD CONSTRAINT "FeatureModule_key_check" CHECK ("key" ~ '^[a-z][a-z0-9_]*$');

ALTER TABLE "ModuleConfiguration"
  ADD CONSTRAINT "ModuleConfiguration_reason_check" CHECK (btrim("reason") <> '');

ALTER TABLE "Permission"
  ADD CONSTRAINT "Permission_key_check"
    CHECK ("resource" ~ '^[a-z][a-z_]*$' AND "action" ~ '^[a-z][a-z_]*$'
           AND "key" = "resource" || ':' || "action");

ALTER TABLE "Role"
  ADD CONSTRAINT "Role_key_check" CHECK ("key" ~ '^[a-z][a-z0-9_]*$');

-- Scope consistency: PLATFORM has no site, SITE has exactly one. No self-grant. Revocation and
-- expiry are coherent.
ALTER TABLE "RoleAssignment"
  ADD CONSTRAINT "RoleAssignment_scope_check"
    CHECK (("scopeType" = 'PLATFORM' AND "siteId" IS NULL)
        OR ("scopeType" = 'SITE' AND "siteId" IS NOT NULL)),
  ADD CONSTRAINT "RoleAssignment_no_self_grant_check"
    CHECK ("grantedById" IS NULL OR "grantedById" <> "userId"),
  ADD CONSTRAINT "RoleAssignment_expiry_check"
    CHECK ("expiresAt" IS NULL OR "expiresAt" > "grantedAt"),
  ADD CONSTRAINT "RoleAssignment_revocation_check"
    CHECK ("revokedById" IS NULL OR "revokedAt" IS NOT NULL);

ALTER TABLE "AuditEvent"
  ADD CONSTRAINT "AuditEvent_scope_check"
    CHECK (("scopeType" = 'PLATFORM' AND "siteId" IS NULL)
        OR ("scopeType" = 'SITE' AND "siteId" IS NOT NULL)),
  ADD CONSTRAINT "AuditEvent_actor_check"
    CHECK (("actorType" = 'USER') = ("actorUserId" IS NOT NULL)),
  ADD CONSTRAINT "AuditEvent_metadata_check" CHECK (jsonb_typeof("metadata") = 'object');

-- A user's kind (STAFF/CUSTOMER) never changes: a customer account cannot be turned into a
-- staff account to inherit staff roles or the staff session policy.
CREATE FUNCTION iam_user_kind_immutable() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF NEW."kind" IS DISTINCT FROM OLD."kind" THEN
    RAISE EXCEPTION 'iam: User.kind is immutable' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "User_kind_immutable" BEFORE UPDATE OF "kind" ON "User"
  FOR EACH ROW EXECUTE FUNCTION iam_user_kind_immutable();

-- Escalation guard: a role is assignable only to users of its audience and only at its scope
-- type. The identity of an assignment (who, which role, where, granted by whom) is immutable;
-- an update may only revoke it or change its expiry.
CREATE FUNCTION iam_role_assignment_guard() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE
  role_audience "UserKind";
  role_scope "ScopeType";
  user_kind "UserKind";
BEGIN
  IF TG_OP = 'UPDATE' AND (
       NEW."userId" IS DISTINCT FROM OLD."userId"
    OR NEW."roleId" IS DISTINCT FROM OLD."roleId"
    OR NEW."scopeType" IS DISTINCT FROM OLD."scopeType"
    OR NEW."siteId" IS DISTINCT FROM OLD."siteId"
    OR NEW."grantedById" IS DISTINCT FROM OLD."grantedById"
    OR NEW."grantedAt" IS DISTINCT FROM OLD."grantedAt") THEN
    RAISE EXCEPTION 'iam: role assignment identity is immutable; revoke and grant instead'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT "audience", "scopeType" INTO role_audience, role_scope FROM "Role" WHERE "id" = NEW."roleId";
  SELECT "kind" INTO user_kind FROM "User" WHERE "id" = NEW."userId";
  IF role_audience IS DISTINCT FROM user_kind THEN
    RAISE EXCEPTION 'iam: role audience does not match the user kind' USING ERRCODE = 'check_violation';
  END IF;
  IF role_scope IS DISTINCT FROM NEW."scopeType" THEN
    RAISE EXCEPTION 'iam: role cannot be assigned at this scope type' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "RoleAssignment_guard" BEFORE INSERT OR UPDATE ON "RoleAssignment"
  FOR EACH ROW EXECUTE FUNCTION iam_role_assignment_guard();

-- God Mode cannot switch off the security core: a core module can never be disabled for a site,
-- lose its core flag, or be removed from the catalogue.
CREATE FUNCTION iam_module_configuration_guard() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF NOT NEW."enabled" AND EXISTS (
       SELECT 1 FROM "FeatureModule" WHERE "id" = NEW."moduleId" AND "isCore") THEN
    RAISE EXCEPTION 'iam: core modules cannot be disabled' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "ModuleConfiguration_guard" BEFORE INSERT OR UPDATE ON "ModuleConfiguration"
  FOR EACH ROW EXECUTE FUNCTION iam_module_configuration_guard();

CREATE FUNCTION iam_feature_module_core_guard() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF OLD."isCore" AND (TG_OP = 'DELETE' OR NOT NEW."isCore") THEN
    RAISE EXCEPTION 'iam: core modules cannot be removed or downgraded' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "FeatureModule_core_guard" BEFORE UPDATE OR DELETE ON "FeatureModule"
  FOR EACH ROW EXECUTE FUNCTION iam_feature_module_core_guard();

-- Audit events are append-only: no UPDATE, DELETE or TRUNCATE. (A database superuser or the
-- table owner can still disable triggers; ADR-011 records the separate runtime role as follow-up.)
CREATE FUNCTION iam_audit_event_append_only() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  RAISE EXCEPTION 'iam: AuditEvent is append-only (% rejected)', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END
$fn$;
CREATE TRIGGER "AuditEvent_append_only" BEFORE UPDATE OR DELETE ON "AuditEvent"
  FOR EACH ROW EXECUTE FUNCTION iam_audit_event_append_only();
CREATE TRIGGER "AuditEvent_no_truncate" BEFORE TRUNCATE ON "AuditEvent"
  FOR EACH STATEMENT EXECUTE FUNCTION iam_audit_event_append_only();
